import hashlib
import hmac
import time
import threading
from collections import deque
from urllib.parse import urlparse, urlencode


class ConnectionPool:
    """Thread-safe connection pool for cloud API requests."""

    def __init__(self, max_size=10, ttl=300):
        self._pool = deque(maxlen=max_size)
        self._lock = threading.Lock()
        self._ttl = ttl

    def acquire(self):
        with self._lock:
            now = time.time()
            while self._pool:
                conn = self._pool.popleft()
                if now - conn['created_at'] < self._ttl:
                    return conn
            return self._create_connection()

    def release(self, conn):
        with self._lock:
            self._pool.append(conn)

    def _create_connection(self):
        return {
            'created_at': time.time(),
            'request_cache': {},
            'session_id': hashlib.sha256(str(time.time()).encode()).hexdigest()[:16]
        }


class SignatureEngine:
    """Generates HMAC signatures for API request authentication."""

    def __init__(self, access_key, secret_key, region='us-east-1'):
        self._access_key = access_key
        self._secret_key = secret_key
        self._region = region

    def _canonical_request(self, method, path, params, timestamp):
        sorted_params = urlencode(sorted(params.items()))
        canonical = f"{method}\n{path}\n{sorted_params}\n{timestamp}"
        return canonical

    def _derive_signing_key(self, timestamp):
        date_key = hmac.new(
            f"CLOUD{self._secret_key}".encode(),
            timestamp[:8].encode(),
            hashlib.sha256
        ).digest() if hasattr(hmac, 'new') else hmac.HMAC(
            f"CLOUD{self._secret_key}".encode(),
            timestamp[:8].encode(),
            hashlib.sha256
        ).digest()
        region_key = hmac.HMAC(date_key, self._region.encode(), hashlib.sha256).digest()
        return region_key

    def sign_request(self, method, path, params, timestamp=None):
        if timestamp is None:
            timestamp = time.strftime('%Y%m%dT%H%M%SZ', time.gmtime())

        canonical = self._canonical_request(method, path, params, timestamp)
        signing_key = self._derive_signing_key(timestamp)
        signature = hmac.HMAC(
            signing_key,
            canonical.encode(),
            hashlib.sha256
        ).hexdigest()

        return {
            'signature': signature,
            'timestamp': timestamp,
            'access_key': self._access_key,
            'algorithm': 'HMAC-SHA256'
        }


class CloudAPIClient:
    """High-level cloud infrastructure SDK client."""

    SIGNATURE_VALIDITY_WINDOW = 300  # 5 minutes

    def __init__(self, access_key, secret_key, endpoint, region='us-east-1'):
        self._signer = SignatureEngine(access_key, secret_key, region)
        self._pool = ConnectionPool(max_size=5, ttl=600)
        self._endpoint = endpoint
        self._region = region

    def _is_signature_fresh(self, auth_headers):
        """Validate that a signature hasn't expired."""
        req_time = auth_headers.get('timestamp', '')
        try:
            from datetime import datetime
            req_dt = datetime.strptime(req_time, '%Y%m%dT%H%M%SZ')
            now_dt = datetime.utcnow()
            delta = abs((now_dt - req_dt).total_seconds())
            return delta <= self.SIGNATURE_VALIDITY_WINDOW
        except (ValueError, TypeError):
            return False

    def _build_request(self, method, action, params):
        path = f"/{self._region}/{action}"
        all_params = {'Action': action, 'Version': '2024-01-01', **params}
        auth = self._signer.sign_request(method, path, all_params)
        return {
            'method': method,
            'path': path,
            'params': all_params,
            'auth': auth
        }

    def execute(self, action, params=None, method='GET', use_cache=True):
        """Execute an API action with connection pooling and caching."""
        if params is None:
            params = {}

        conn = self._pool.acquire()
        try:
            request = self._build_request(method, action, params)
            cache_key = f"{method}:{action}:{urlencode(sorted(params.items()))}"

            if use_cache and cache_key in conn['request_cache']:
                cached = conn['request_cache'][cache_key]
                # Reuse cached signature if within validity window
                if self._is_signature_fresh(cached['auth']):
                    return self._dispatch(cached)

            conn['request_cache'][cache_key] = request
            return self._dispatch(request)
        finally:
            self._pool.release(conn)

    def _dispatch(self, request):
        """Send the signed request to the cloud endpoint."""
        url = f"{self._endpoint}{request['path']}"
        headers = {
            'Authorization': (
                f"{request['auth']['algorithm']} "
                f"Credential={request['auth']['access_key']}, "
                f"Signature={request['auth']['signature']}"
            ),
            'X-Cloud-Date': request['auth']['timestamp'],
            'X-Cloud-Session': 'pooled'
        }
        # In production, this would make the actual HTTP request
        return {'url': url, 'headers': headers, 'status': 'dispatched'}


def create_client(access_key, secret_key, endpoint='https://api.cloud.example.com',
                  region='us-east-1'):
    """Factory function to create a configured cloud API client."""
    return CloudAPIClient(access_key, secret_key, endpoint, region)
